refentry.refsect1:
  &reftitle.examples;

   TimeTicks とテーブルのインデックスの形式を変える


<?php

var_dump(snmp2_get('localhost', 'public', 'SNMPv2-MIB::sysUpTime.0'));

snmp_set_output_option(Snmp\Output::NumericTimeticks, true);
var_dump(snmp2_get('localhost', 'public', 'SNMPv2-MIB::sysUpTime.0'));

snmp_set_output_option(Snmp\Output::ExtendedIndex, true);
var_dump(snmp2_real_walk('localhost', 'public', 'IF-MIB::ifDescr'));

?>


   &example.outputs.similar;


string(40) "Timeticks: (14096763) 1 day, 15:09:27.63"
string(8) "14096763"
array(2) {
  ["IF-MIB::ifDescr[1]"]=>
  string(10) "STRING: lo"
  ["IF-MIB::ifDescr[2]"]=>
  string(12) "STRING: eth0"
}
